style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com") {
body {
        background: url("https://i.imgur.com/MdyD5On.jpeg") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* Make all main containers transparent or semi-transparent */
    div, section, main {
        background-color: rgba(255, 255, 255, 0.7) !important;
    }

    /* Optional: Remove full white overlay if it exists */
    #root, .app, .theme-base {
        background: transparent !important;
    }

    /* Improve scrollbar visibility */
    ::-webkit-scrollbar {
        background: rgba(0, 0, 0, 0.2);
    }

    ::-webkit-scrollbar-thumb {
        background: rgba(0, 0, 0, 0.5);
    }
}
